round:var(--blue);color:white;border-color:var(--blue)}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin-bottom:14px}.stat{padding:15px;display:flex;align-items:center;gap:12px;min-width:0}.ico{width:45px;height:45px;display:grid;place-items:center;border-radius:13px;background:#eaf2ff;color:var(--blue);font-size:23px;flex-shrink:0}.stat:nth-child(2) .ico{background:#e2f8ef;color:var(--green)}.stat:nth-child(3) .ico{background:#fff1d8;color:var(--orange)}.stat:nth-child(4) .ico{background:#ffe8e8;color:var(--red)}.stat small{display:block;color:var(--muted);margin-bottom:7px}.stat strong{font-size:26px}.filters{padding:15px;display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:10px;margin-bottom:14px}.field label{display:block;font-weight:bold;font-size:12px;margin-bottom:7px}.field input,.field select{width:100%;height:41px;border:1px solid #dce4ef;border-radius:9px;padding:0 10px;background:#fff;color:#30455f;min-width:0}.tablehead{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:16px;border-bottom:1px solid var(--line)}.tablehead h2{font-size:16px;margin:0}.tablehead p{font-size:12px;color:var(--muted);margin:5px 0 0}.tablewrap{overflow-x:auto}table{width:100%;min-width:950px;border-collapse:collapse}thead{background:#f7f9fc}th,td{text-align:right;padding:13px 11px;border-bottom:1px solid #edf1f6;white-space:nowrap}th{font-size:12px;color:#53647a}td{font-size:12px}tbody tr:hover{background:#fbfdff}.company{display:flex;gap:9px;align-items:center;min-width:190px}.companyicon{width:34px;height:34px;border-radius:10px;background:#eaf2ff;color:var(--blue);display:grid;place-items:center;font-weight:bold}.company b{display:block}.company small{display:block;color:var(--muted);margin-top:4px}.badge{display:inline-block;padding:6px 9px;border-radius:8px;font-size:11px;font-weight:bold}.active{background:#e2f8ef;color:var(--green)}.paused{background:#fff1d8;color:var(--orange)}.expired{background:#ffe8e8